// Des: Tests for the step runner against the mock ZenRows site (real headless Chrome)
// Flo: build steps > run in the rig > check page effects, records, typed errors
// I/O: none (mock site on loopback, scratch profile) > pass or fail (skips without Chrome)
// Run: cd E:\zz-base-home\as-apps\in-inte\zr-zrow-webs && zig build test -Dfile=ru-flow-runz-test.zig
// ===================================================================
const std = @import("std"); const rigz = @import("te-rigz-brow.zig"); const flow = @import("ru-flow-runz.zig"); const stat = @import("st-stat-main.zig");
fn runOf(rig: *rigz.Rig, store: ?*stat.Stat) flow.Run { return .{ .env = rig.env(), .store = store, .base = rig.base() }; }
test "login flow end to end: goto, type, click, expect (auth run allows the login page)" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); var run = runOf(&rig, null); run.auth = true; const stps = [_]flow.Step{ .{ .op = .goto, .text = "/login" }, .{ .op = .typez, .labs = &.{"Email"}, .text = "a@b.co" }, .{ .op = .typez, .labs = &.{"Password"}, .text = "pw1" }, .{ .op = .click, .labs = &.{"Log in"}, .commit = true }, .{ .op = .expect, .labs = &.{"dashboard"} } }; try flow.runSteps(&run, &stps); try std.testing.expectEqual(@as(u32, 5), run.done); try std.testing.expect(run.crossed); const rec = rig.waitRec("btn", 3000).?; try std.testing.expect(std.mem.find(u8, rec, "Log in|a@b.co|pw1") != null); }
test "the login page without auth gives NeedLogin" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); var run = runOf(&rig, null); const stps = [_]flow.Step{.{ .op = .goto, .text = "/login" }}; try std.testing.expectError(error.NeedLogin, flow.runSteps(&run, &stps)); }
test "captcha and suspended pages stop the flow with Halted, nothing is written" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); var run = runOf(&rig, null); run.auth = true; const cap = [_]flow.Step{ .{ .op = .goto, .text = "/captcha" }, .{ .op = .click, .labs = &.{"x"} } }; try std.testing.expectError(error.Halted, flow.runSteps(&run, &cap)); try std.testing.expectEqual(@as(usize, 0), rig.mock.recCnt()); const sus = [_]flow.Step{.{ .op = .goto, .text = "/suspended" }}; try std.testing.expectError(error.Halted, flow.runSteps(&run, &sus)); }
test "a banned key page is UNSAFE" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); var run = runOf(&rig, null); const blk = [_]flow.Step{.{ .op = .goto, .text = "/blocked" }}; try std.testing.expectError(error.Unsafe, flow.runSteps(&run, &blk)); try std.testing.expectEqual(@as(?@import("ru-safe-halt.zig").Halt, .blocked), run.hltk); }
test "missing label gives NoElement after the retry budget" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); rig.conf.retr_coun_maxz = 2; var run = runOf(&rig, null); const stps = [_]flow.Step{ .{ .op = .goto, .text = "/support" }, .{ .op = .click, .labs = &.{"no such button"} } }; try std.testing.expectError(error.NoElement, flow.runSteps(&run, &stps)); }
test "expect times out as Drift" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); var run = runOf(&rig, null); const stps = [_]flow.Step{ .{ .op = .goto, .text = "/support" }, .{ .op = .expect, .labs = &.{"never on this page"}, .ms = 600 } }; try std.testing.expectError(error.Drift, flow.runSteps(&run, &stps)); }
test "pause flag stops the flow before any step" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); var pth: [128]u8 = undefined; const dbp = try std.mem.printSentinel(&pth, ".zig-cache/tmp/{s}/zr.db", .{rig.tmpz.sub_path}, 0); var sto = try stat.Stat.open(std.testing.allocator, dbp); defer sto.close(); try sto.flagSet("pause", true); var run = runOf(&rig, &sto); const stps = [_]flow.Step{.{ .op = .goto, .text = "/support" }}; try std.testing.expectError(error.Paused, flow.runSteps(&run, &stps)); try std.testing.expectEqual(@as(u32, 0), run.done); }
test "a known popup is dismissed after page load, then the page works" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); var run = runOf(&rig, null); const stps = [_]flow.Step{ .{ .op = .goto, .text = "/popup/" }, .{ .op = .click, .labs = &.{"Do thing"} } }; try flow.runSteps(&run, &stps); try std.testing.expect(rig.waitPre("popup|closed", 3000)); try std.testing.expect(rig.waitPre("btn|Do thing", 3000)); }
test "an unknown dialog on load halts for the owner (overlay, needs you)" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); var run = runOf(&rig, null); const stps = [_]flow.Step{ .{ .op = .goto, .text = "/cookie" }, .{ .op = .click, .labs = &.{"x"} } }; try std.testing.expectError(error.Halted, flow.runSteps(&run, &stps)); }
test "a rate-limit dialog is UNSAFE" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); var run = runOf(&rig, null); const stps = [_]flow.Step{.{ .op = .goto, .text = "/ratelimit" }}; try std.testing.expectError(error.Unsafe, flow.runSteps(&run, &stps)); }
test "toggle reaches the wanted state once and does nothing when already there" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); var run = runOf(&rig, null); const on = [_]flow.Step{ .{ .op = .goto, .text = "/toggle/" }, .{ .op = .toggle, .labs = &.{"Notifications"}, .text = "on" } }; try flow.runSteps(&run, &on); try std.testing.expectEqualStrings("Notifications=on", rig.waitRec("tog", 3000).?); const again = [_]flow.Step{.{ .op = .toggle, .labs = &.{"Notifications"}, .text = "on" }}; try flow.runSteps(&run, &again); try std.testing.expectEqual(@as(usize, 1), rig.mock.recNum("tog")); }
test "select picks an option from a combobox" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); var run = runOf(&rig, null); const stps = [_]flow.Step{ .{ .op = .goto, .text = "/fetch" }, .{ .op = .select, .labs = &.{"Language"}, .text = "python" } }; try flow.runSteps(&run, &stps); try std.testing.expectEqualStrings("Language=python", rig.waitRec("opt", 3000).?); }
test "file upload sets the file input; clear then type replaces a value" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); const pth = try rig.absOf("urls.txt"); try std.Io.Dir.cwd().writeFile(rig.iozz, .{ .sub_path = try std.fmt.allocPrint(rig.aren.allocator(), ".zig-cache/tmp/{s}/urls.txt", .{rig.tmpz.sub_path}), .data = "https://example.com\n" }); var run = runOf(&rig, null); const up = [_]flow.Step{ .{ .op = .goto, .text = "/batch" }, .{ .op = .upload, .text = pth } }; try flow.runSteps(&run, &up); try std.testing.expectEqualStrings("1", rig.waitRec("file", 3000).?); const rep = [_]flow.Step{ .{ .op = .goto, .text = "/settings/account" }, .{ .op = .clear, .labs = &.{"Name"} }, .{ .op = .typez, .labs = &.{"Name"}, .text = "New Name" }, .{ .op = .click, .labs = &.{"Save"} } }; try flow.runSteps(&run, &rep); const rec = rig.waitRec("btn", 3000).?; try std.testing.expect(std.mem.find(u8, rec, "Save|New Name") != null); try std.testing.expect(std.mem.find(u8, rec, "Old Name") == null); }
test "cool pace doubles the gaps but still completes" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); var run = runOf(&rig, null); run.cool = true; const stps = [_]flow.Step{ .{ .op = .goto, .text = "/support" }, .{ .op = .click, .labs = &.{"Send"} } }; try flow.runSteps(&run, &stps); try std.testing.expect(rig.waitPre("btn|Send", 3000)); }
